# Synthetic bounded workflow

Use only the supplied in-memory world.

```tsg-workflow
{
  "version": 1,
  "steps": [
    {
      "id": "a001_f890c",
      "kind": "effect",
      "op": "write",
      "resource": "/synthetic/phase10/f890c1898a/out",
      "value": "copper:307"
    },
    {
      "id": "a002_f890c",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase10/f890c1898a/switch",
      "out": "mode_f890c"
    },
    {
      "id": "a005_f890c",
      "kind": "if",
      "eq": [
        {
          "var": "mode_f890c"
        },
        "keep"
      ],
      "then": [
        {
          "id": "a003_f890c",
          "kind": "effect",
          "op": "read",
          "resource": "/synthetic/phase10/f890c1898a/out",
          "out": "check_f890c"
        }
      ],
      "else": [
        {
          "id": "a004_f890c",
          "kind": "effect",
          "op": "read",
          "resource": "/synthetic/phase10/f890c1898a/source",
          "out": "check_f890c"
        }
      ]
    },
    {
      "id": "a006_f890c",
      "kind": "effect",
      "op": "write",
      "resource": "/synthetic/phase10/f890c1898a/out",
      "value": {
        "var": "check_f890c"
      }
    },
    {
      "id": "a007_f890c",
      "kind": "effect",
      "op": "emit",
      "resource": "/synthetic/phase10/f890c1898a/audit",
      "value": "seen"
    },
    {
      "id": "a008_f890c",
      "kind": "let",
      "name": "unused_f890c",
      "value": {
        "concat": [
          {
            "var": "check_f890c"
          },
          "/ignored"
        ]
      }
    },
    {
      "id": "a010_f890c",
      "kind": "repeat",
      "count": 0,
      "body": [
        {
          "id": "a009_f890c",
          "kind": "effect",
          "op": "delete",
          "resource": "/synthetic/phase10/f890c1898a/cold"
        }
      ]
    }
  ],
  "functions": {}
}
```

